        "实际流程：先只在训练集拟合中心与尺度；对中心化矩阵做 SVD；取前 r 个右奇异向量为载荷；用相同转换投影新样本。解释方差高不代表保留了全部分类信息。",
        "PCA 在第 4 章作为构造少量自变量的方法，在第 9 章与因子分析、监督降维、非线性降维比较。相同单元可从两个章节进入，学习证据只记一次。"
