      "why": "画混淆矩阵 → 说明错误代价。先做本节的小例子，再把条件和结论连起来。",
      "intro": [
        "准确率是全部预测中正确的比例；当正类很少时，全预测负类也能看起来很高。Precision 关注判正中多少是真的，Recall 关注真阳性中找回多少。",
        "ROC 描述 TPR 与 FPR 的权衡，PR 曲线更直接展示正类检索表现；二者回答不同问题。阈值应由验证数据和错误成本选择，概率质量还要看校准与对数损失。"
      ],
      "simple": "找回所有坏零件和避免把好零件误判成坏品，是两个不同的目标。",
      "formula": "Precision=TP/(TP+FP)；Recall=TP/(TP+FN)；F1=2PR/(P+R)",
      "terms": {
        "TP": "真阳性",
        "FP": "假阳性",
        "FN": "漏检的阳性",
        "阈值": "把概率变成决策的门槛"
      },
      "example": "TP=30、FP=10、FN=20、TN=40，计算 Precision 和 Recall。",
      "steps": [
        [
          "看预测为正",
          "30+10=40，其中 30 真实，Precision=0.75。"
        ],
        [
          "看实际为正",
          "30+20=50，找回 30，Recall=0.6。"
        ],
        [
          "综合",
          "F1=2×0.75×0.6/(1.35)=2/3。"
        ]
      ],
      "trap": "AUC 不等于某阈值下准确率；类别不平衡时应报告不止一个指标与基率。",
