      "title": "SNE 与 t-SNE：邻居图不能当精确地图",
      "group": "第9章 · 降维方法介绍",
      "pre": [
        "bayesrule",
        "mds"
      ],
      "method": "局部概率 → 看谁是邻居",
      "why": "局部概率 → 看谁是邻居。先做本节的小例子，再把条件和结论连起来。",
      "intro": [
        "SNE 把高维邻近关系写成条件概率，让低维中的邻近概率与其匹配。t-SNE 使用对称概率与低维重尾分布，缓解拥挤问题；它是相关改进方法，不是 SNE 的完全同义词。",
        "这些方法主要服务于局部结构可视化。不同随机种子、perplexity 和预处理可能给出不同图；簇间空白、簇大小和远距离不能直接照搬成统计结论。"
      ],
      "simple": "把熟人尽量安排在同桌，不要求每两桌间的距离对应他们现实中的亲疏程度。",
      "formula": "KL(P||Q)=Σpᵢⱼ log(pᵢⱼ/qᵢⱼ)",
      "terms": {
        "P": "高维邻近关系的概率",
        "Q": "低维邻近关系的概率",
        "perplexity": "邻域尺度相关参数，不是类别数量"
      },
      "example": "高维中 A 最靠近 B。嵌入后 A 与 B 很远，但另两簇距离看起来漂亮。这个图好吗？",
      "steps": [
        [
          "检查目标",
          "优先检查局部邻居是否保留。"
        ],
        [
          "发现损失",
          "把高概率邻居分开会受到 KL 的惩罚。"
        ],
        [
          "解释图",
          "不能因簇间布局漂亮就宣称保留了全部几何关系。"
        ]
      ],
      "trap": "t-SNE 散点分成团不自动证明存在真实类别；禁止用测试标签挑出最满意的可视化后再当无监督发现。",
